window.RP_SESSION={"id":"S-a08e080c694e","messages":[{"id":"RP-II-0115567","time":"2026-07-07T00:35:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"어제는 무슨 잔치가 있었는지 장에서 소고기가 다 팔려서 구하지 못했습니다.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0115568","time":"2026-07-07T00:35:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"그래서 오늘 다시 장에 가서 소고기를 사왔죠.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0115569","time":"2026-07-07T00:35:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"!민첩","characters":["P-fec1db60d51e"]},{"id":"RP-II-0115570","time":"2026-07-07T00:35:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'레마 캐롤라인'의 민첩 판정 :\n[4] + [3] = [7]\n결과 : 쓰라린 실패, 운명을 빗겨갈 순 없습니다.","characters":[]},{"id":"RP-II-0115571","time":"2026-07-07T00:35:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"음, 오늘도 좀 늦었는지 기름기가 그리 많은 덩어리는 아니군요.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0115572","time":"2026-07-07T00:36:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"어제 쓰려고 했던 좋은 숯을 꺼내 와서, 화로에 채워놓고 부싯돌과 불쏘시개 등으로 불을 붙입니다.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0115573","time":"2026-07-07T00:37:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"화로 전체에 열기가 퍼지기 전에, 빠르게 재료를 손질합니다.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0115574","time":"2026-07-07T00:37:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"고기는 적절한 두께로 썰어 천으로 수분을 닦아내고, 소금을 뿌려 둡니다.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0115575","time":"2026-07-07T00:38:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"버섯도 한 입 크기로 잘라 꼬치에 꿰고, 채소들도 화로 위에서 굽기 좋은 크기로 자릅니다.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0115576","time":"2026-07-07T00:54:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"화덕에서 열이 적당히 올라오자 석쇠에 적당히 기름을 바르고 위에 고기, 채소, 버섯을 얹어서","characters":["P-fec1db60d51e"]},{"id":"RP-II-0115577","time":"2026-07-07T00:56:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"숯의 열기에 재료들이 적절히 익어가자 그릇에 담고 다시 한 번 간해서 한 조각 톡 집어먹으면!","characters":["P-fec1db60d51e"]},{"id":"RP-II-0115578","time":"2026-07-07T00:56:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"숯 향과 재료 본연의 향이 잘 어우러지는 모듬구이 완성!","characters":["P-fec1db60d51e"]},{"id":"RP-II-0115580","time":"2026-07-08T22:25:00+09:00","room":"RP II","name":"올리브","profile":"올리브","identity":"unresolved","type":"dialogue","body":"-fin","characters":[]}]};
